UPDATE mf_mail SET sender = #{entity.sender}, recipient = #{entity.recipient}, subject = #{entity.subject}, body = #{entity.body},
folder = #{entity.folder}, starred = #{entity.starred}, unread = #{entity.unread}, account_id = #{entity.accountId}, updated_at = CURRENT_TIMESTAMP
WHERE user_id = #{entity.userId} AND id = #{entity.id}

UPDATE mf_mail SET folder = COALESCE(#{folder}, folder), starred = COALESCE(#{starred}, starred), unread = COALESCE(#{unread}, unread),
flags_version = flags_version + 1,
updated_at = CURRENT_TIMESTAMP WHERE user_id = #{userId} AND id = #{id}

